class Person:
    def __init__(self, name, age):
        self._name = name
        self._age = age

    @property
    def age(self):
        return self._age

    def __str__(self):
        return f"Person({self._name}, {self._age})"

class Employee(Person):
    def __init__(self, name, age, salary):
        super().__init__(name, age)
        self.salary = salary

emp = Employee("Bob", 30, 75000)
print(str(emp))
print(f"Age property: {emp.age}")
